/**
 * Render every code-built email to HTML files + an index page.
 *   npx tsx scripts/email-preview.ts [outDir=/tmp/nxeon-email-preview]
 * Uses lib/email-samples.ts (the same samples the tracking tests use).
 */
import "../test/_cyrus-server-only-shim";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { SAMPLES } from "../lib/email-samples";

const out = process.argv[2] ?? "/tmp/nxeon-email-preview";
mkdirSync(out, { recursive: true });
const rows: string[] = [];
for (const [key, build] of Object.entries(SAMPLES)) {
  const b = build();
  writeFileSync(join(out, `${key}.html`), b.html);
  rows.push(`<li><a href="${key}.html">${key}</a> <small>${b.subject.replace(/</g, "&lt;")}</small></li>`);
}
writeFileSync(join(out, "index.html"), `<!doctype html><meta charset="utf-8"><title>Nxeon emails</title><body style="font-family:sans-serif;background:#070a1a;color:#fff"><h1>${rows.length} templates</h1><ul>${rows.join("")}</ul>`);
console.log(`wrote ${rows.length} templates to ${out}`);
/**
 * Sample renders of EVERY code-built transactional email (the `emails` catalog
 * in lib/email-templates.ts + the billing/dunning set in lib/mailer.ts).
