import "./_cyrus-server-only-shim";
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { SAMPLES, SAMPLE_UNSUB, catalogKeys } from "../lib/email-samples";
import { injectEmailTracking } from "../lib/mailer";
import { containsSecretQueryParam, htmlToText, wrapEmail, BRAND } from "../lib/email-render";

/**
 * Email overhaul guard (board card "Overhaul email templates"). Every code-built
 * email must (1) sit on the ONE shared shell, (2) keep every link / unsubscribe
 * hook the pre-overhaul template had (baseline fixture captured from main before
 * the change), and (3) still be trackable: open pixel + click rewrite work, and
 * bearer-secret links stay untouched.
 */
const APP = process.env.APP_URL ?? "https://nxeon.cloud";
const baseline = JSON.parse(readFileSync(join(__dirname, "fixtures", "email-tracking-inventory.json"), "utf8")) as Record<string, { subject: string; hrefs: string[] }>;
const hrefsOf = (html: string) => [...html.matchAll(/href="(https?:\/\/[^"]+)"/g)].map((m) => m[1].split(APP).join("{APP}"));

test("every template in the catalog has a sample (new emails cannot ship unchecked)", () => {
  const missing = catalogKeys().filter((k) => !(k in SAMPLES));
  assert.deepEqual(missing, []);
});

for (const [key, build] of Object.entries(SAMPLES)) {
  test(`${key}: shared shell, tracking hooks and plain text`, () => {
    const b = build();
    assert.ok(b.subject.length > 0);
    assert.ok(b.html.startsWith("<!doctype html>"), "full document");
    assert.ok(b.html.includes("/brand/logo-email.png"), "logo header");
    assert.ok(b.html.includes("NXEON CLOUD") || b.html.includes("CYRUS"), "footer");
    assert.ok(b.html.includes(BRAND.card), "dark card");
    assert.ok(!/\{\{|undefined|\[object Object\]/.test(b.html), "no unrendered placeholders");
    assert.ok(b.html.trimEnd().endsWith("</body></html>"), "</body> last so the pixel can be injected");

    // Every pre-overhaul link is still present (multiset subset).
    const before = baseline[key];
    if (before && !before.subject.startsWith("ERROR")) {
      const now = hrefsOf(b.html);
      const pool = [...now];
      for (const h of before.hrefs) {
        const i = pool.indexOf(h);
        // flashSale's old Outlook VML duplicated the CTA href; one copy is enough.
        if (i < 0 && key === "flashSale" && now.includes(h)) continue;
        assert.ok(i >= 0, `${key}: lost link ${h}`);
        pool.splice(i, 1);
      }
    }

    // Tracking: pixel appended, every non-secret absolute link rewritten, secrets untouched.
    const t = injectEmailTracking(b.html, "log-1");
    assert.equal((t.html.match(/\/api\/track\/email\/log-1\/open/g) ?? []).length, 1, "one open pixel");
    for (const h of hrefsOf(b.html).map((x) => x.split("{APP}").join(APP))) {
      const secret = containsSecretQueryParam(h) || h.includes("/api/outreach/unsubscribe");
      if (secret) assert.ok(t.html.includes(`href="${h}"`), `secret/unsubscribe link must stay direct: ${h}`);
      else assert.ok(t.links.includes(h), `link not tracked: ${h}`);
    }
    // Plain-text alternative: real content, no CSS/markup leakage.
    const text = htmlToText(b.html);
    assert.ok(text.length > 40);
    assert.ok(!/[{};]\s*\.nx-|<\w+|@media/.test(text), "no CSS or tags in text part");
  });
}

test("marketing templates keep their unsubscribe link (untracked, token-bearing) and the sample unsub URL", () => {
  for (const k of ["onboardingTips", "onboardingExplore", "onboardingCheckIn", "deployWinback", "dormantWinback", "flashSale"]) {
    const html = SAMPLES[k]().html;
    assert.ok(html.includes(`href="${SAMPLE_UNSUB}"`), `${k}: unsubscribe link`);
    assert.ok(containsSecretQueryParam(SAMPLE_UNSUB));
  }
});

test("the mailer still sends RFC 8058 List-Unsubscribe headers and tracks via injectEmailTracking", () => {
  const src = readFileSync(join(__dirname, "..", "lib", "mailer.ts"), "utf8");
  assert.match(src, /"List-Unsubscribe": `<\$\{opts\.listUnsubscribeUrl\}>`/);
  assert.match(src, /"List-Unsubscribe-Post": "List-Unsubscribe=One-Click"/);
  assert.match(src, /injectEmailTracking\(html, emailLogId\)/);
  assert.match(src, /\/api\/track\/email\/\$\{emailLogId\}\/click\/\$\{idx\}/);
});

test("legacy light-theme colours in stored bodies are remapped, bare links and bold get readable colours", () => {
  const html = wrapEmail(`<p style="color:#1c1638">Hi <a href="https://x.test/a">link</a> <b>bold</b> <span style="color:#6f47f5">v</span></p>`);
  assert.ok(!html.includes("#1c1638") && !html.includes("#6f47f5"));
});

test("htmlToText drops styles, keeps link targets", () => {
  const t = htmlToText(`<html><head><style>.a{color:red}</style></head><body><p>Hello&nbsp;<a href="https://x.test/p">there</a></p><p>Bye</p></body></html>`);
  assert.equal(t, "Hello there (https://x.test/p)\nBye");
});
#!/bin/bash
# =============================================================================
# devhost — run agent dev work on the BUILD HOST (node-2), not on the primary.
#
# Edit files on the primary as usual (your own git worktree — never /opt/nxeon),
# then run every heavy command through this helper. It mirrors your worktree's
# source to node-2 (/tank/nxeon-build/wt/<name>, own node_modules there), runs the
# command inside the capped nxeon-build-agents.slice with a THROWAWAY database
# (Postgres on node-2 127.0.0.1:5433), and streams the output back.
#
#   scripts/devhost run [--lock] [--max SEC] -- CMD...   push + run CMD in the node-2 copy
#   scripts/devhost tsc                                  = run -- npx tsc --noEmit
#   scripts/devhost test [FILES...]                      = run --lock -- npx tsx --test ...
#   scripts/devhost build                                = run --lock -- npx next build
#   scripts/devhost dev [--port P]                       start `next dev` on node-2 (background unit)
#   scripts/devhost bg NAME [--port P] -- CMD...         any background process (worker, preview server)
#   scripts/devhost stop [NAME|all]                      stop this worktree's background units
#   scripts/devhost logs [NAME] [-n N] [-f]              journal of a background unit (default: dev)
#   scripts/devhost tunnel PORT [LOCAL_PORT]             ssh -L so the primary can curl/Playwright it
#   scripts/devhost pull REMOTE_PATH [LOCAL_DEST]        copy results (screenshots, reports) back
#   scripts/devhost push                                 just sync files (run does this itself)
#   scripts/devhost install                              force npm install + prisma generate there
#   scripts/devhost db push|reset|info                   throwaway DB: schema push / recreate / name
#   scripts/devhost env set KEY=VALUE | unset KEY | list extra env for this worktree (never prod secrets)
#   scripts/devhost rm                                   stop units, drop the throwaway DB, delete the node-2 copy
#   scripts/devhost ls | status | sync                   workspaces / node-2 load / push refs to node-2's mirror
#
# Rules: /root/agent-notes/BUILD-HOST.md. The node-2 copy is a build/run sandbox,
# not a place to edit or commit — your primary-side worktree stays the source of truth.
# =============================================================================
set -euo pipefail
HERE="$(dirname "$(readlink -f "$0")")"
# shellcheck source=lib/buildhost-env.sh
source "$HERE/lib/buildhost-env.sh"
REPO="${DEVHOST_REPO:-/opt/nxeon}"

die() { echo "devhost: $*" >&2; exit 1; }
say() { echo "devhost: $*" >&2; }
q() { printf '%q ' "$@"; }

