import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { emails } from "../lib/email-templates";

const base = { hostname: "gabriel-trial", planName: "Pro", dashboardUrl: "https://nxeon.cloud/dashboard/servers/abc" };
const text = (html: string) => html.replace(/<[^>]+>/g, " ").replace(/&nbsp;|&#8199;/g, " ").replace(/\s+/g, " ");

test("a shared-NAT VPS email includes the SSH port", () => {
  const e = emails.serverDeployed({ ...base, sshEndpoint: "51.79.162.96:20076" });
  assert.match(text(e.html), /ssh root@51\.79\.162\.96 -p 20076/);
});

test("a dedicated-IP VPS email has no port", () => {
  const t = text(emails.serverDeployed({ ...base, sshEndpoint: "15.235.171.189" }).html);
  assert.match(t, /ssh root@15\.235\.171\.189(?! -p)/);
  assert.doesNotMatch(t, / -p \d/);
});

test("the root-password location differs for a VPS and a game server", () => {
  const vps = text(emails.serverDeployed({ ...base, sshEndpoint: "1.2.3.4:20001" }).html);
  assert.match(vps, /Root access/);
  assert.doesNotMatch(vps, /Show password/);
  const game = text(emails.serverDeployed({ ...base, sshEndpoint: "1.2.3.4:20001", gameLabel: "Minecraft", gameConnect: "1.2.3.4:20002" }).html);
  assert.match(game, /Access/);
  assert.match(game, /SSH access/);
  assert.match(game, /root password/i);
  assert.doesNotMatch(game, /Root access card/);
  assert.match(game, /1\.2\.3\.4:20002/);
});

