// ===========================================================================
// SHELL V2 — the 2026-10 mockup ("Nxeon email templates" board image, 8 phone
// panels). Built first for the server-deployed email only (owner review gate);
// every other template still uses wrapEmail() above until that is approved.
//
// Rules this section follows (Gmail / Outlook / Apple Mail / mobile safe):
//  - table layout, inline CSS; every gradient / background-image sits on top
//    of a solid bgcolor + background-color fallback (Outlook desktop and some
//    Gmail apps drop images/gradients and get the flat navy instead);
//  - border-radius is decoration only (Outlook squares it, layout unchanged);
//  - every image is an absolute https URL under `${APP_URL}/email/` (PNG/JPG
//    only; built by scripts/email-assets.py), with width/height + alt text;
//  - no `href="https://..."` on <link>: lib/mailer.ts rewrites EVERY absolute
//    href into the click redirect, so the web font is pulled with @import;
//  - `</body>` stays last (open pixel insertion point).
// ===========================================================================

/** Palette sampled from the mockup panels. */
export const NX2 = {
  page: "#04060f",
  shell: "#070a18",
  shellBorder: "#1b2036",
  hair: "#1a2034",
  card: "#10162a",
  cardTop: "#151c33",
  cardBottom: "#0c1121",
  cardBorder: "#242b45",
  tile: "#0d1324",
  tileTop: "#121a2f",
  tileBorder: "#1f2742",
  ink: "#ffffff",
  body: "#c5c9d6",
  label: "#9aa1b6",
  muted: "#8a90a6",
  faint: "#555c76",
  eyebrow: "#c48cf0",
  violet: "#7c3aed",
  violetA: "#7a3ff6",
  violetB: "#9152ff",
  secondary: "#28385a",
  secondaryA: "#2d3e60",
  secondaryB: "#24324f",
  pillBg: "#0b2f2b",
  pillBorder: "#1d7f69",
  pillInk: "#7ef0c6",
  link: "#b69cff",
};
const FONT2 = "Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
/** Absolute URL of a file under public/email/. */
export const emailAsset = (p: string) => `${appUrl()}/email/${p.replace(/^\/+/, "")}`;

/** Hero: full-bleed background art (per game) with the eyebrow, big headline and lead text over it. */
export function emailHero2(a: { image?: string; eyebrow: string; title: string; titleSuffix?: string; text?: string }): string {
  const img = a.image ?? emailAsset("games/hero-default.jpg");
  const lines = esc(a.title).replace(/\n/g, "<br/>");
  return `<tr><td class="nx2-hero" background="${img}" bgcolor="${NX2.shell}" valign="top" style="background-color:${NX2.shell};background-image:url('${img}');background-size:cover;background-position:right top;background-repeat:no-repeat;padding:46px 40px 34px;">
  <div style="margin:0 0 16px;font-family:${FONT2};font-size:13px;line-height:16px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;color:${NX2.eyebrow};">${esc(a.eyebrow)}</div>
  <h1 class="nx2-h1" style="margin:0 0 20px;font-family:${FONT2};font-size:50px;line-height:56px;font-weight:800;letter-spacing:-1.4px;color:${NX2.ink};">${lines}${a.titleSuffix ? `&nbsp;${a.titleSuffix}` : ""}</h1>
  ${a.text ? `<p class="nx2-lead" style="margin:0;max-width:420px;font-family:${FONT2};font-size:18px;line-height:28px;color:${NX2.body};">${themeInline2(a.text)}</p>` : ""}
</td></tr>`;
}

function themeInline2(html: string): string {
  return String(html ?? "")
    .replace(/<a\s+(?![^>]*\bstyle=)([^>]*?)>/gi, `<a $1 style="color:${NX2.link};text-decoration:underline;">`)
    .replace(/<(b|strong)>/gi, `<$1 style="color:${NX2.ink};font-weight:600;">`);
}

/** A padded body section row; `inner` is any block markup. */
export function emailSection2(inner: string, pad = "0 40px 20px"): string {
  return `<tr><td class="nx2-px" style="padding:${pad};font-family:${FONT2};">${inner}</td></tr>`;
}

export type InfoRow = { label: string; value: string; copy?: boolean; flagCc?: string; mono?: boolean };

/** Status pill (the mockup's green "Online"). */
export function emailPill2(label: string): string {
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" align="right"><tr><td bgcolor="${NX2.pillBg}" style="background-color:${NX2.pillBg};border:1px solid ${NX2.pillBorder};border-radius:999px;padding:7px 16px;font-family:${FONT2};font-size:14px;line-height:16px;font-weight:600;color:${NX2.pillInk};white-space:nowrap;">${esc(label)}</td></tr></table>`;
}

/** Full-width primary (violet) or secondary (slate) button. */
export function emailButton2(href: string, label: string, kind: "primary" | "secondary" = "primary"): string {
  const p = kind === "primary";
  const bg = p ? NX2.violet : NX2.secondary;
  const grad = p ? `linear-gradient(90deg,${NX2.violetA} 0%,${NX2.violetB} 100%)` : `linear-gradient(180deg,${NX2.secondaryA} 0%,${NX2.secondaryB} 100%)`;
  const shadow = p ? "box-shadow:0 10px 28px rgba(124,58,237,0.38);" : "";
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" bgcolor="${bg}" style="background-color:${bg};background-image:${grad};border-radius:12px;${shadow}">
  <a href="${href}" style="display:block;padding:${p ? 18 : 15}px 20px;font-family:${FONT2};font-size:${p ? 17 : 16}px;line-height:20px;font-weight:${p ? 700 : 600};color:#ffffff;text-decoration:none;border-radius:12px;">${esc(label)}&nbsp;&rarr;</a>
</td></tr></table>`;
}

const cardOpen = (pad: string) =>
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${NX2.card}" style="background-color:${NX2.card};background-image:linear-gradient(180deg,${NX2.cardTop} 0%,${NX2.cardBottom} 100%);border:1px solid ${NX2.cardBorder};border-radius:18px;"><tr><td style="padding:${pad};font-family:${FONT2};">`;
const cardClose = `</td></tr></table>`;

/**
 * Info card: icon tile + title (+ sub) + status pill, hairline key/value rows
 * (copy glyph / flag per row), optional note and a full-width button.
 * Values are escaped; `note` is trusted inline markup.
 */
export function emailInfoCard2(a: {
  tile?: { src: string; alt: string };
  title: string;
  titleHref?: string;
  sub?: string;
  pill?: string;
  rows: InfoRow[];
  note?: string;
  cta?: { href: string; label: string };
}): string {
  const title = a.titleHref
    ? `<a href="${a.titleHref}" style="color:${NX2.ink};text-decoration:none;">${esc(a.title)}</a>`
    : esc(a.title);
  const head = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
    ${a.tile ? `<td width="64" valign="middle" style="width:64px;padding:0 0 0 0;"><img src="${a.tile.src}" width="48" height="48" alt="${esc(a.tile.alt)}" style="display:block;width:48px;height:48px;border:0;border-radius:12px;" /></td>` : ""}
    <td valign="middle" style="font-family:${FONT2};">
      <div style="font-size:18px;line-height:24px;font-weight:700;color:${NX2.ink};word-break:break-word;">${title}</div>
      ${a.sub ? `<div style="font-size:13px;line-height:18px;color:${NX2.muted};padding-top:2px;">${esc(a.sub)}</div>` : ""}
    </td>
    ${a.pill ? `<td width="96" valign="middle" align="right" style="width:96px;">${emailPill2(a.pill)}</td>` : ""}
  </tr></table>`;
  const rows = a.rows
    .map((r) => {
      const flag = r.flagCc
        ? `<img src="${emailAsset(`flags/${r.flagCc}.png`)}" width="24" height="16" alt="" style="display:inline-block;width:24px;height:16px;border:0;border-radius:3px;vertical-align:-3px;margin-right:10px;" />`
        : "";
      const val = `${flag}${esc(r.value)}`;
      const valStyle = r.mono ? `font-family:'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace;font-size:14px;` : `font-family:${FONT2};font-size:15px;`;
      return `<tr>
        <td class="nx2-k" width="34%" valign="middle" style="width:34%;padding:16px 0;border-top:1px solid ${NX2.hair};font-family:${FONT2};font-size:15px;line-height:20px;color:${NX2.label};">${esc(r.label)}</td>
        <td valign="middle" style="padding:16px 0;border-top:1px solid ${NX2.hair};${valStyle}line-height:20px;font-weight:500;color:#e8eaf2;word-break:break-all;">${val}</td>
        <td width="24" valign="middle" align="right" style="width:24px;padding:16px 0;border-top:1px solid ${NX2.hair};">${r.copy ? `<img src="${emailAsset("icons/copy.png")}" width="20" height="20" alt="" style="display:block;width:20px;height:20px;border:0;" />` : "&nbsp;"}</td>
      </tr>`;
    })
    .join("");
  return `${cardOpen("22px 24px 24px")}
    ${head}
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:18px;border-bottom:1px solid ${NX2.hair};">${rows}</table>
    ${a.note ? `<p style="margin:18px 0 0;font-family:${FONT2};font-size:14px;line-height:22px;color:${NX2.muted};">${themeInline2(a.note)}</p>` : ""}
    ${a.cta ? `<div style="height:22px;line-height:22px;font-size:0;">&nbsp;</div>${emailButton2(a.cta.href, a.cta.label)}` : ""}
  ${cardClose}`;
}

/** 2-column grid of quick-action tiles (icon tile + title + one line), each a link. */
export function emailActionGrid2(tiles: Array<{ icon: string; title: string; text: string; href: string }>): string {
  const cell = (t: (typeof tiles)[number] | undefined, side: "l" | "r") =>
    t
      ? `<td class="nx2-qa" width="50%" valign="top" style="width:50%;padding:${side === "l" ? "0 7px 14px 0" : "0 0 14px 7px"};">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${NX2.tile}" style="background-color:${NX2.tile};background-image:linear-gradient(180deg,${NX2.tileTop} 0%,${NX2.tile} 100%);border:1px solid ${NX2.tileBorder};border-radius:16px;"><tr>
        <td width="44" valign="middle" style="width:44px;padding:18px 0 18px 16px;"><a href="${t.href}" style="text-decoration:none;"><img src="${t.icon}" width="44" height="44" alt="" style="display:block;width:44px;height:44px;border:0;" /></a></td>
        <td valign="middle" style="padding:16px 12px 16px 14px;font-family:${FONT2};">
          <a href="${t.href}" style="text-decoration:none;display:block;"><span style="display:block;font-size:15px;line-height:20px;font-weight:700;color:${NX2.ink};">${esc(t.title)}</span><span style="display:block;font-size:13px;line-height:18px;color:${NX2.muted};padding-top:3px;">${esc(t.text)}</span></a>
        </td>
      </tr></table></td>`
      : `<td width="50%" style="width:50%;">&nbsp;</td>`;
  let rows = "";
  for (let i = 0; i < tiles.length; i += 2) rows += `<tr>${cell(tiles[i], "l")}${cell(tiles[i + 1], "r")}</tr>`;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${rows}</table>`;
}

/** Secondary "Need help?" card: title, one paragraph, slate full-width button. */
export function emailHelpCard2(a: { title: string; text: string; cta: { href: string; label: string } }): string {
  return `${cardOpen("24px 24px 24px")}
    <div style="font-family:${FONT2};font-size:18px;line-height:24px;font-weight:700;color:${NX2.ink};">${esc(a.title)}</div>
    <p style="margin:8px 0 20px;font-family:${FONT2};font-size:15px;line-height:23px;color:${NX2.body};">${themeInline2(a.text)}</p>
    ${emailButton2(a.cta.href, a.cta.label, "secondary")}
  ${cardClose}`;
}

/** Small muted paragraph inside a section (fine print, how-to notes). */
export function emailNote2(html: string): string {
  return `<p style="margin:0;font-family:${FONT2};font-size:14px;line-height:22px;color:${NX2.muted};">${themeInline2(html)}</p>`;
