f='lib/email-templates.ts'; s=open(f).read()
start=s.index('  serverDeployed: (a: {')
end=s.index('  // ---- Growth / win-back')
new='''  serverDeployed: (a: {
    hostname: string;
    planName: string;
    sshEndpoint: string;
    dashboardUrl: string;
    gameLabel?: string;
    gameConnect?: string;
    /** GameFamily slug (lib/games.ts) — picks the hero art + icon tile. */
    gameFamily?: string;
    /** Node.region code (lib/node-regions.ts), e.g. "sgp1" → "Singapore" + flag. */
    region?: string;
    /** Operator-configured social profiles (lib/social-links.ts getSocialLinks()). */
    socials?: EmailSocial[];
  }): BuiltEmail => {
    const isGame = !!a.gameLabel;

    // Split "<host>:<port>" (NAT) vs "<host>" (dedicated) into an ssh command.
    const idx = a.sshEndpoint.lastIndexOf(":");
    const host = idx > 0 ? a.sshEndpoint.slice(0, idx) : a.sshEndpoint;
    const port = idx > 0 ? a.sshEndpoint.slice(idx + 1) : "";
    const sshCmd = port ? `ssh root@${host} -p ${port}` : `ssh root@${host}`;

    // Game join address "<host>:<port>" → the card's IP Address / Port rows.
    const gi = a.gameConnect ? a.gameConnect.lastIndexOf(":") : -1;
    const joinHost = a.gameConnect ? (gi > 0 ? a.gameConnect.slice(0, gi) : a.gameConnect) : host;
    const joinPort = a.gameConnect ? (gi > 0 ? a.gameConnect.slice(gi + 1) : "") : port;

    const fam = isGame && a.gameFamily && EMAIL_GAME_ART.has(a.gameFamily) ? a.gameFamily : null;
    const heroImg = emailAsset(fam ? `games/hero-${fam}.jpg` : "games/hero-default.jpg");
    const tileImg = emailAsset(fam ? `games/tile-${fam}.png` : "games/tile-default.png");
    const regionLabel = a.region ? customerRegionLabel(a.region) : "";
    const regionCc = a.region ? REGION_COUNTRY[a.region] : undefined;

    const rows: InfoRow[] = [
      { label: "IP Address", value: joinHost, copy: true },
      ...(joinPort ? [{ label: isGame ? "Port" : "SSH Port", value: joinPort, copy: true }] : []),
      ...(regionLabel ? [{ label: "Region", value: regionLabel, flagCc: regionCc }] : []),
      { label: "Plan", value: a.planName },
    ];
    const tab = (t: string) => `${a.dashboardUrl}${a.dashboardUrl.includes("?") ? "&" : "?"}tab=${t}`;
    const tiles = isGame
      ? [
          { icon: emailAsset("icons/qa-power.png"), title: "Start Server", text: "Power on or off", href: a.dashboardUrl },
          { icon: emailAsset("icons/qa-mods.png"), title: "Install Mods", text: "Mods & plugins", href: tab("mods") },
          { icon: emailAsset("icons/qa-console.png"), title: "View Console", text: "Real-time logs", href: tab("console") },
          { icon: emailAsset("icons/qa-files.png"), title: "Manage Files", text: "SFTP / File Manager", href: tab("files") },
        ]
      : [
          { icon: emailAsset("icons/qa-console.png"), title: "Open Console", text: "Browser terminal", href: tab("console") },
          { icon: emailAsset("icons/qa-files.png"), title: "Manage Files", text: "Browse & upload", href: tab("files") },
          { icon: emailAsset("icons/qa-backups.png"), title: "Backups", text: "Archives & snapshots", href: tab("backups") },
          { icon: emailAsset("icons/qa-network.png"), title: "Networking", text: "Firewall & ports", href: tab("networking") },
        ];

    const panelLink = (label: string) => `<a href="${a.dashboardUrl}" style="color:${NX2.link};text-decoration:none;font-weight:600;">${label}</a>`;
    const body = [
      emailHero2({
        image: heroImg,
        eyebrow: "Server deployed",
        title: "Your server\\nis ready!",
        titleSuffix: "\\u{1F389}",
        text: isGame
          ? `Good news! Your ${escHtml(a.gameLabel!)} server has been deployed and is ready to play.`
          : "Good news! Your server has been deployed and is ready to use.",
      }),
      emailSection2(
        emailInfoCard2({
          tile: { src: tileImg, alt: isGame ? a.gameLabel! : "Server" },
          title: a.hostname,
          titleHref: a.dashboardUrl,
          sub: isGame ? `${a.gameLabel} server` : "Cloud VPS",
          pill: "Online",
          rows,
          note: isGame
            ? a.gameConnect
              ? `Add <b>${escHtml(a.gameConnect)}</b> to your game client's multiplayer server list to connect. Your server is ready to play right away!`
              : "Add this address in your game client's multiplayer server list to connect. Your server is ready to play right away!"
            : undefined,
          cta: { href: a.dashboardUrl, label: "Manage Server" },
        }),
        "6px 40px 16px"
      ),
      ...(isGame
        ? []
        : [
            emailSection2(
              `<div style="font-family:inherit;font-size:15px;line-height:22px;font-weight:700;color:#ffffff;margin:0 0 10px;">Connect over SSH</div>${emailCode2(sshCmd)}<div style="height:12px;line-height:12px;font-size:0;">&nbsp;</div>${emailNote2(
                `Your root password is on your server's page in the dashboard, in the <b>Root access</b> card (click to reveal it) — for your security we never put it in an email. Getting started: run <b>apt update &amp;&amp; apt upgrade</b> (Debian/Ubuntu) once you're in.`
              )}`,
              "8px 40px 22px"
            ),
          ]),
      emailSection2(emailActionGrid2(tiles), "6px 40px 4px"),
      ...(isGame
        ? [
            emailSection2(
              emailNote2(
                `Need SSH or SFTP access to the server's files? Open your ${panelLink("game panel")} and go to the <b>Access</b> tab: the <b>SSH access</b> card shows the exact command and your root password (click to reveal it). For your security we never put passwords in an email.`
              ),
              "4px 40px 22px"
            ),
          ]
        : [emailSection2(emailNote2(`Manage power, backups, firewall and more from your ${panelLink("server dashboard")}.`), "4px 40px 22px")]),
      emailSection2(
        emailHelpCard2({
          title: "Need help?",
          text: `Check out our ${isGame ? "game server " : ""}guides or <a href="${LINKS.support()}" style="color:${NX2.link};text-decoration:none;">contact our support team</a> anytime.`,
          cta: { href: path("/help"), label: "View Guides" },
        }),
        "0 40px 26px"
      ),
    ].join("\\n");

    return {
      template: "server_deployed",
      subject: isGame
        ? `Your ${a.gameLabel} server ${a.hostname} is ready \\u{1F3AE}`
        : `Your Nxeon server ${a.hostname} is ready \\u{1F680}`,
      html: wrapEmail2(body, {
        preheader: isGame
          ? `${a.hostname} is online — jump in and start playing.`
          : `${a.hostname} is provisioned and online — connect over SSH in seconds.`,
        socials: a.socials,
      }),
    };
  },

'''
s=s[:start]+new+s[end:]
s=s.replace('''  type Accent,
} from "@/lib/email-render";''','''  type Accent,
  NX2,
