s+='''
test("server deployed (shell v2): per-game hero + tile, region flag, configured socials only, email-safe images", () => {
  const mc = SAMPLES.serverDeployed().html;
  assert.ok(mc.includes(`${APP}/email/games/hero-minecraft.jpg`), "minecraft hero");
  assert.ok(mc.includes(`${APP}/email/games/tile-minecraft.png`), "grass block tile");
  assert.ok(mc.includes(`${APP}/email/flags/sg.png`) && mc.includes("Singapore"), "region + flag");
  for (const k of ["mc-survival-01", "Game Server 4GB", "play.example.com", "25565", "Online", "Manage Server", "View Guides"]) assert.ok(mc.includes(k), k);
  const vh = SAMPLES.serverDeployedValheim().html;
  assert.ok(vh.includes("hero-valheim.jpg") && vh.includes("tile-valheim.png") && vh.includes("flags/de.png"));
  const vps = SAMPLES.serverDeployedVps().html;
  assert.ok(vps.includes("hero-default.jpg") && vps.includes("tile-default.png"));
  // socials: exactly what was passed, nothing invented
  const none = (SAMPLES.serverDeployed as unknown as () => { html: string }) && mc;
  assert.ok(none.includes("/email/social/discord.png"));
  for (const html of [mc, vh, vps]) {
    for (const m of html.matchAll(/<img\\b[^>]*>/g)) {
      const tag = m[0];
      assert.match(tag, /src="https:\\/\\/[^"]+\\.(png|jpe?g)"/, `absolute png/jpg: ${tag}`);
      assert.match(tag, /\\bwidth="\\d+"/, `width: ${tag}`);
      assert.match(tag, /\\bheight="\\d+"/, `height: ${tag}`);
      assert.match(tag, /\\balt="/, `alt: ${tag}`);
    }
    assert.ok(!/<link\\b[^>]*href=/.test(html), "no <link href> (the click rewrite would break it)");
  }
});
'''
